// ============================================================
// LẤY "TỪ ĐIỂN" + GIÁ TRỊ các dòng BCTC năm gần nhất (VNM)
// modelType:1 = Kết quả KD (có Lợi nhuận sau thuế)
// modelType:2 = Cân đối kế toán (có Vốn chủ, Nợ, Tài sản)
// Mục tiêu: thấy itemCode + itemName để tính ROE = LNST/VCSH.
// ============================================================
const headers = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
  'Accept': 'application/json, text/plain, */*',
  'Referer': 'https://dstock.vndirect.com.vn/',
};

const fetchStmt = async (modelType) => {
  // thử xin kèm itemName; nếu API không hỗ trợ field vẫn trả các field mặc định
  const url = 'https://api-finfo.vndirect.com.vn/v4/financial_statements?q=code:VNM~modelType:' + modelType + '~reportType:ANNUAL&fields=itemCode,itemName,numericValue,fiscalDate&sort=fiscalDate:desc&size=200';
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url, headers, json: false, timeout: 20000 });
    let p; try { p = typeof res === 'string' ? JSON.parse(res) : res; } catch (e) { return { err: 'parse', raw: String(res).slice(0, 150) }; }
    return { data: (p && p.data) || [] };
  } catch (e) {
    return { err: (e.message || String(e)) };
  }
};

const out = [];
for (const [mt, label] of [[1, 'KQKD (Kết quả kinh doanh)'], [2, 'CĐKT (Cân đối kế toán)']]) {
  const r = await fetchStmt(mt);
  if (r.err) { out.push({ json: { stmt: label, status: '❌ ' + r.err, raw: r.raw || '' } }); continue; }
  // chỉ lấy năm tài chính mới nhất
  let maxDate = '';
  for (const d of r.data) if ((d.fiscalDate || '') > maxDate) maxDate = d.fiscalDate;
  const rows = r.data.filter(d => d.fiscalDate === maxDate);
  out.push({ json: { stmt: label, status: '✅ ' + rows.length + ' dòng, năm ' + maxDate + (rows[0] && rows[0].itemName !== undefined ? ' (CÓ itemName)' : ' (KHÔNG có itemName)') } });
  for (const d of rows.sort((a, b) => Number(a.itemCode) - Number(b.itemCode))) {
    out.push({ json: { stmt: label.slice(0, 4), itemCode: d.itemCode, itemName: (d.itemName || '(không có tên)'), value: d.numericValue } });
  }
}
return out;
